    describe2("ElementsSurfaceChrome", () => {
      it2("keeps dark class while nested leases are active", () => {
        resetElementsSurfaceChromeForTests();
        const outer = applyElementsSurfaceChrome({ appearance: "dark", device: "desktop", expertise: "normal" /* NORMAL */ });
        const inner = applyElementsSurfaceChrome({ appearance: "light", device: "desktop", expertise: "normal" /* NORMAL */ });
        expect(document.documentElement.classList.contains("dark")).toBe(false);
        inner();
        expect(document.documentElement.classList.contains("dark")).toBe(true);
        outer();
        expect(document.documentElement.classList.contains("dark")).toBe(true);
        resetElementsSurfaceChromeForTests();
        expect(document.documentElement.classList.contains("dark")).toBe(false);
      });
      it2("reapplies the previous lease after the top lease releases", () => {
        resetElementsSurfaceChromeForTests();
        const outer = applyElementsSurfaceChrome({ appearance: "dark", device: "desktop", expertise: "normal" /* NORMAL */, compact: false });
        const inner = applyElementsSurfaceChrome({ appearance: "dark", device: "tablet", expertise: "normal" /* NORMAL */, compact: true });
        expect(document.documentElement.dataset.uiDevice).toBe("tablet");
        expect(document.documentElement.dataset.uiCompact).toBe("true");
        inner();
        expect(document.documentElement.dataset.uiDevice).toBe("desktop");
        expect(document.documentElement.dataset.uiCompact).toBe("false");
        outer();
        resetElementsSurfaceChromeForTests();
      });
      it2("defers clearing dark until the next animation frame when the last lease releases", () => {
        resetElementsSurfaceChromeForTests();
        let scheduled;
        const raf = vi.spyOn(globalThis, "requestAnimationFrame").mockImplementation((callback) => {
          scheduled = callback;
          return 1;
        });
        const release = applyElementsSurfaceChrome({ appearance: "dark", device: "desktop", expertise: "normal" /* NORMAL */ });
        release();
        expect(document.documentElement.classList.contains("dark")).toBe(true);
        expect(raf).toHaveBeenCalled();
        scheduled?.(0);
        expect(document.documentElement.classList.contains("dark")).toBe(false);
        raf.mockRestore();
        resetElementsSurfaceChromeForTests();
      });
      it2("bootstrapElementsSurfaceChromeDocument applies explicit dark before leases exist", () => {
        resetElementsSurfaceChromeForTests();
        bootstrapElementsSurfaceChromeDocument("dark");
        expect(document.documentElement.classList.contains("dark")).toBe(true);
        expect(document.documentElement.dataset.uiAppearance).toBe("dark");
        resetElementsSurfaceChromeForTests();
      });
      it2("applies touch chrome and the mobile device attribute for the mobile device", () => {
        resetElementsSurfaceChromeForTests();
        const release = applyElementsSurfaceChrome({ appearance: "light", device: "mobile", expertise: "normal" /* NORMAL */ });
        expect(document.documentElement.classList.contains("touch")).toBe(true);
        expect(document.documentElement.dataset.uiDevice).toBe("mobile");
        release();
        resetElementsSurfaceChromeForTests();
      });
      it2("clears touch chrome for the desktop device", () => {
        resetElementsSurfaceChromeForTests();
        const release = applyElementsSurfaceChrome({ appearance: "light", device: "desktop", expertise: "normal" /* NORMAL */ });
        expect(document.documentElement.classList.contains("touch")).toBe(false);
        expect(document.documentElement.dataset.uiDevice).toBe("desktop");
        release();
        resetElementsSurfaceChromeForTests();
      });
    });
